import os, warnings, pickle
warnings.filterwarnings('ignore')
import numpy as np, pandas as pd
from pymatgen.core import Structure, Element
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from ase.data import covalent_radii
from collections import defaultdict

tr=pd.read_csv('/work/nlo_shg_eg_train.csv');po=pd.read_csv('/work/nlo_pool.csv');df=pd.concat([tr,po],ignore_index=True)
structures=[Structure.from_str(x,fmt='poscar') for x in df.poscar]

def safe(x):
 try: return float(x)
 except: return np.nan

def props(el):
 vals={k:safe(getattr(el,k,None)) for k in ['Z','X','atomic_mass','atomic_radius','atomic_radius_calculated','row','group','mendeleev_no','molar_volume','melting_point','boiling_point','electron_affinity','thermal_conductivity']}
 vals['ionization']=safe(el.ionization_energies[0]);vals['covalent_radius']=covalent_radii[el.Z]
 vals['maxoxi']=el.max_oxidation_state; vals['minoxi']=el.min_oxidation_state
 for b in ['s','p','d','f']:
  vals['valence_'+b]=sum(n for r,bb,n in el.full_electronic_structure if bb==b and ((r==el.row) or (b=='d' and r==el.row-1) or (b=='f' and r==el.row-2)))
 vals['outer_electrons']=vals['valence_s']+vals['valence_p']
 return vals
elprops={e:props(Element(e)) for s in structures for e in s.composition.get_el_amt_dict()}
rows=[];infos=[]
for idx,s in enumerate(structures):
 f={};comp=s.composition.fractional_composition.get_el_amt_dict();els=list(comp);w=np.array(list(comp.values()));ep=pd.DataFrame([elprops[e] for e in els]);maxx=max(ep.X)
 for e in elprops: f['fraction_'+e]=comp.get(e,0)
 f['nelements']=len(els); f['entropy']=-np.sum(w*np.log(w));f['stoich2']=sum(w*w);f['stoich3']=sum(w**3)**(1/3)
 for pop,sel in [('all',np.ones(len(els),bool)),('cation',np.array([elprops[e]['X']<maxx-.1 for e in els])),('anion',np.array([elprops[e]['X']>=maxx-.1 for e in els]))]:
  ww=w[sel]; ww=ww/ww.sum() if ww.sum() else ww
  for k in ep:
   a=ep[k].values[sel];mask=np.isfinite(a)
   if not mask.any(): continue
   a=a[mask];ws=ww[mask];ws=ws/ws.sum();av=sum(a*ws)
   for st,v in [('mean',av),('min',min(a)),('max',max(a)),('std',sum(ws*(a-av)**2)**.5)]: f[f'{pop}_{k}_{st}']=v
 for group in range(1,19): f[f'groupfrac_{group}']=sum(comp[e] for e in els if Element(e).group==group)
 f['enrange']=max(ep.X)-min(ep.X);f['ionicity']=1-np.exp(-f['enrange']**2/4)
 sg=SpacegroupAnalyzer(s,symprec=.05); pg=sg.get_point_group_symbol();sgno=sg.get_space_group_number()
 f['spacegroup']=sgno; f['polar']=int(pg in ['1','2','m','mm2','3','3m','4','4mm','6','6mm']);f['centrosym']=int(sg.is_laue())
 for p in ['1','2','m','222','mm2','3','3m','32','4','-4','-42m','4mm','6mm','23','-43m']: f['pg_'+p]=int(p==pg)
 for cs in ['triclinic','monoclinic','orthorhombic','tetragonal','trigonal','hexagonal','cubic']: f['system_'+cs]=int(sg.get_crystal_system()==cs)
 f['vpa']=s.volume/len(s); f['density']=float(s.density); f['natom']=len(s);f['nprimitive']=len(sg.find_primitive())
 try: f['inequiv_frac']=len(sg.get_symmetrized_structure().equivalent_indices)/len(s)
 except: f['inequiv_frac']=1
 lengths=np.sort(s.lattice.abc);f['lattice_anisotropy']=lengths[-1]/lengths[0]
 f['packing']=4*np.pi/3*sum(covalent_radii[a.specie.Z]**3 for a in s)/s.volume
 cis,njs,imgs,ds=s.get_neighbor_list(6.5)
 rd=[[] for _ in range(4)];cation_coord=[];anion_coord=[];bondlens=[];bondrel=[];bonddx=[];angle3=[];angle2=[]
 tensors=defaultdict(lambda:np.zeros((3,3,3)));ntens=defaultdict(float);onsite=[];siteCN=[];tet=[];localpolar=[]
 types={str(site.specie) for site in s}
 site_info=[]
 for i,site in enumerate(s):
  e=str(site.specie);X=site.specie.X;sel=(cis==i);inds=njs[sel];dd=ds[sel];im=imgs[sel]
  ord=np.argsort(dd)
  for k in range(4): rd[k].append(dd[ord[k]])
  # Consistent nearest-shell cutoff; tetrahedral semiconductor and lone-pair shells separated from longer contacts.
  keep=dd < dd.min()*1.22
  inds=inds[keep];dd=dd[keep];im=im[keep]
  u=np.array([(s[j].frac_coords+imj-site.frac_coords)@s.lattice.matrix/d for j,imj,d in zip(inds,im,dd)])
  CN=len(dd);siteCN.append(CN)
  pt=np.einsum('bi,bj,bk->ijk',u,u,u);pn=np.linalg.norm(pt)/CN;pp=np.linalg.norm(u.sum(axis=0))/CN
  localpolar.append(pp);onsite.append(pn);site_info.append((e,CN,round(float(dd.mean()),3),round(pp,3),round(pn,3)))
  if X<maxx-.1: cation_coord.append(CN)
  else: anion_coord.append(CN)
  cang=u@u.T;cang=cang[np.triu_indices(CN,1)]
  if len(cang):
   tet.append(np.mean((cang+1/3)**2)); angle3.append(np.mean((cang+.5)**2));angle2.append(np.mean(cang**2))
  for j,v,d in zip(inds,u,dd):
   e2=str(s[j].specie);dx=s[j].specie.X-X
   bondlens.append(d);bondrel.append(d/(covalent_radii[site.specie.Z]+covalent_radii[s[j].specie.Z]));bonddx.append(abs(dx))
   if dx<=.05: continue
   t=np.einsum('i,j,k->ijk',v,v,v)
   for label,weight in [('all',1),('en',dx),('en_inv',1/(dx+.5)),('covalent',np.exp(-dx**2/4)),('volume',d**3),('metal_'+e,1),('anion_'+e2,1),('group_'+str(site.specie.group),1)]:
    tensors[label]+=weight*t;ntens[label]+=weight
  tensors['site_'+e]+=pt;ntens['site_'+e]+=CN
 for label in ['all','en','en_inv','covalent','volume']+['metal_'+e for e in elprops]+['anion_'+e for e in elprops]+['site_'+e for e in elprops]+['group_'+str(g) for g in range(1,19)]:
  t=tensors[label];n=ntens[label]
  f['bondtensor_'+label+'_density']=np.linalg.norm(t)/s.volume
  f['bondtensor_'+label+'_coherence']=np.linalg.norm(t)/(n+1e-12)
  if label in ['all','en','en_inv','covalent','volume']:
   f['bondtensor_'+label+'_maxdensity']=np.max(abs(t))/s.volume
 for name,a in [('bondlen',bondlens),('bondrel',bondrel),('bond_en',bonddx),('coord',siteCN),('catcoord',cation_coord),('ancoord',anion_coord),('tetdistort',tet),('trigdistort',angle3),('angle2',angle2),('localpolar',localpolar),('localtensor',onsite)]+[('dist'+str(k+1),rd[k]) for k in range(4)]:
  if not a: a=[0]
  f[name+'_mean']=np.mean(a);f[name+'_std']=np.std(a);f[name+'_min']=np.min(a);f[name+'_max']=np.max(a)
 for cn in range(1,9): f['coordfrac_'+str(cn)]=np.mean(np.array(siteCN)==cn)
 f['valencedensity']=f['all_outer_electrons_mean']/f['vpa']
 rows.append(f);infos.append(dict(sg=sgno,pg=pg,sites=site_info))
 if idx%50==0: print(idx,flush=True)
X=pd.DataFrame(rows).fillna(0);X=X.loc[:,X.nunique()>1]
pickle.dump((X,structures,infos),open('/tmp/nlo_features.pkl','wb'))
print(X.shape)

